<section><div class="contact-toolbar"><div><p class="eyebrow">CONTABILIDAD · <?= $page['type'] === 'customer' ? 'CLIENTES' : 'PROVEEDORES' ?></p><h1>Facturas de <?= $page['type'] === 'customer' ? 'clientes' : 'proveedores' ?></h1><p class="section-subtitle"><?= $page['total'] ?> registros</p></div></div>
    <p class="section-subtitle">Genera las facturas desde la orden de <?= $page['type'] === 'customer' ? 'venta' : 'compra' ?> o su <?= $page['type'] === 'customer' ? 'entrega' : 'recepción' ?> relacionada.</p>
    <form class="contact-filters" method="get" action="index.php"><input type="hidden" name="type" value="<?= $page['type'] ?>"><?php foreach(['sale_id','purchase_id'] as $relatedKey): ?><?php if($relatedId=salesId($_GET[$relatedKey]??null)): ?><input type="hidden" name="<?= $relatedKey ?>" value="<?= $relatedId ?>"><?php endif; ?><?php endforeach; ?><?php foreach(['pending','unpaid','overdue'] as $summaryFilter): ?><?php if(($_GET[$summaryFilter]??'')==='1'): ?><input type="hidden" name="<?= $summaryFilter ?>" value="1"><?php endif; ?><?php endforeach; ?><label>Buscar<input type="search" name="q" maxlength="160" value="<?= accountingEscape($page['search']) ?>" placeholder="Referencia o contacto"></label><label>Estado<select name="status" data-auto-submit><option value="all">Todos</option><?php foreach (invoiceFilterStates() as $value => $label): ?><option value="<?= $value ?>" <?= $page['statusFilter'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><button class="contact-button" type="submit">Buscar</button></form>
    <div class="contact-table-wrap"><table class="contact-table"><thead><tr><th scope="col">Referencia</th><th scope="col"><?= $page['type'] === 'customer' ? 'Cliente' : 'Proveedor' ?></th><th scope="col">Fecha</th><th scope="col">Vencimiento</th><th scope="col">Total</th><th scope="col">Estado</th><th scope="col">Estado de pago</th></tr></thead><tbody><?php foreach ($page['rows'] as $row): ?><tr><td><a class="contact-name" href="index.php?type=<?= $page['type'] ?>&amp;id=<?= (int) $row['id'] ?>"><?= accountingEscape($row['name']) ?></a><?= $row['document_type']==='credit'?' · Nota de crédito':'' ?></td><td><?= accountingEscape($row['contact_name']) ?></td><td><?= accountingEscape($row['invoice_date']) ?></td><td><?= accountingEscape($row['due_date'] ?? '—') ?></td><td><?= accountingEscape($row['total_amount'].' '.$row['currency_code']) ?></td><td><?= invoiceStatuses()[$row['status']] ?><?= $row['sent_at'] ? ' · Enviado' : '' ?></td><td><?= $row['status'] === 'posted' ? invoicePaymentStates()[$row['payment_state']] : '—' ?></td></tr><?php endforeach; ?><?php if (! $page['rows']): ?><tr><td colspan="7" class="contact-empty">No hay facturas que coincidan con los filtros.</td></tr><?php endif; ?></tbody></table></div>
    <nav class="contact-pagination"><span>Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach (['Anterior' => $page['currentPage'] - 1, 'Siguiente' => $page['currentPage'] + 1] as $label => $number): ?><?php if ($number >= 1 && $number <= $page['pages']): ?><a class="contact-button" href="index.php?<?= accountingEscape(http_build_query(['type' => $page['type'], 'q' => $page['search'], 'status' => $page['statusFilter'], 'page' => $number, 'sale_id'=>salesId($_GET['sale_id']??null), 'purchase_id'=>salesId($_GET['purchase_id']??null),'unpaid'=>(($_GET['unpaid']??'')==='1'?'1':null),'overdue'=>(($_GET['overdue']??'')==='1'?'1':null)])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav>
</section>
